(()=>{'use strict';const C=MissionCore,B=MissionBank,root=document.querySelector('#scienceMissions'),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let state=C.clean(null,B),unsaved=false,notice='Mission progress saves on this browser. Include it in your dashboard backup.',selected=B[0].id;
function read(k){try{return JSON.parse(localStorage.getItem(k)||'null')}catch(e){return null}}
function get(){if(!unsaved)state=C.clean(read(C.key),B);return state;}
function save(){try{localStorage.setItem(C.key,JSON.stringify(state));unsaved=false;notice='Mission progress saved on this browser.'}catch(e){unsaved=true;notice='Storage is unavailable or full. Progress is kept for this visit only; back it up from the dashboard.'}window.dispatchEvent(new Event('science-progress-changed'));}
function evidence(){const course=CourseCore.clean(read('science-studio-objectives-v1'),ObjectiveCourse),video=VideoProgress.get().results;return {course,video};}
function ready(m,e){const o=ObjectiveCourse.find(q=>q.id===m.objective);return CourseCore.complete(o,e.course[m.objective])&&e.video[m.video]?.latest===VideoGuides[m.video].correct;}
function summary(){const records=get().records,e=evidence(),rows=B.map(m=>({...m,status:C.status(m,records[m.id],ready(m,e),Date.now()),record:records[m.id]}));return {rows,practised:rows.filter(m=>m.record?.practiceAt).length,badges:rows.filter(m=>m.status==='demonstrated').length};}
function recommended(){const s=DashboardCore.summarise(ObjectiveCourse,read('science-studio-objectives-v1'),ExamBank,read('science-studio-exam-v1'),read('science-studio-mocks-v1'),read('science-studio-plan-v1'),ExamCore,MockCore,CourseCore);return C.recommend(B,get().records,s.gaps.map(x=>x.id),VideoProgress.summary().rows.filter(v=>v.checked&&!v.correct).map(v=>v.id),Date.now());}
const names={ready:'Ready to begin',practising:'Practising',challenge:'Application challenge',waiting:'Follow-up scheduled',recheck:'Follow-up ready',demonstrated:'Demonstrated'};
function dashboard(){const s=summary(),p=recommended();return `<section class="mission-dashboard"><div class="sectionhead"><div><p class="eyebrow">SCIENCE MISSIONS</p><h3>Build skills. Show your reasoning.</h3></div><span class="pill">${s.badges}/${B.length} SKILL BADGES</span></div><p>${s.practised} guided missions completed · ${s.rows.filter(x=>x.status==='recheck').length} follow-ups ready. Badges recognise these specific challenges, not whole-topic mastery.</p>${MissionRewards.panel(s.rows,B,true)}<div class="mission-picks">${p.map(m=>`<button data-mission-open="${m.id}"><small>${esc(m.reason)}</small><strong>${esc(m.title)}${m.extension?' · EXT':''}</strong><span>Open mission →</span></button>`).join('')||'<p>No further mission suggestions right now. Check all missions for scheduled follow-ups, or use a new mock to test wider understanding.</p>'}</div><button data-route="scienceMissions">All missions &amp; skill badges →</button></section>`;}
function milestones(){const overview=document.querySelector('#missionOverview');if(overview)overview.innerHTML=dashboard();const s=summary();for(const t of ['genetics','evolution','rates','heat']){const rows=s.rows.filter(m=>m.topic===t),p=rows.filter(m=>m.record?.practiceAt).length,b=rows.filter(m=>m.status==='demonstrated').length,el=document.querySelector(`[data-area="${t}"]`);if(!el)continue;el.dataset.milestone=b?'demonstrated':p?'practised':'ready';let label=el.querySelector('.bench-milestone');if(!label){label=document.createElement('span');label.className='bench-milestone';el.append(label)}label.textContent=`${b?`${b}/${rows.length} skill badges`:p?`${p}/${rows.length} missions practised`:'Missions ready'}`;}}
function question(m,r,stage,disabled){const i=stage==='initial'?0:1,q=m.questions[i],a=r?.[stage];return `<form data-mission-answer="${stage}"><fieldset ${disabled?'disabled':''}><legend>${stage==='initial'?'Application challenge':'Follow-up challenge'} · ${esc(q.question)}</legend>${q.options.map((v,n)=>`<label><input type="radio" name="mission-${stage}" value="${n}" required ${a?.answer===n?'checked':''}> ${esc(v)}</label>`).join('')}<button type="submit">Check reasoning</button></fieldset>${a?`<p class="mission-feedback" role="status">${a.answer===q.correct?'Correct.':'Not yet.'} ${esc(q.feedback)}</p>`:''}</form>`;}
function render(){const all=summary(),m=B.find(x=>x.id===selected),r=get().records[m.id],e=evidence(),s=C.status(m,r,ready(m,e),Date.now()),o=ObjectiveCourse.find(q=>q.id===m.objective),courseDone=CourseCore.complete(o,e.course[m.objective]),videoDone=e.video[m.video]?.latest===VideoGuides[m.video].correct;root.innerHTML=`<div class="sectionhead"><div><p class="eyebrow">SCIENCE MISSIONS / YEAR 10</p><h2>Earn the evidence.</h2></div><span class="pill">${all.badges}/${B.length} SKILL BADGES</span></div><p>Explore, explain, apply, then return for a different question after 24 hours. There are no points for opening a resource and no lost streaks. Your badge recognises a small set of demonstrated skills, not an official assessment.</p><p class="small">The interval uses this device’s clock. Previously completed objective and video checks count towards guided practice. Model reflections are self-reported.</p><p role="status" class="small" data-mission-notice>${esc(notice)}</p>${MissionRewards.panel(all.rows,B)}<div class="mission-badges" aria-label="Skill badges and mission selection">${all.rows.map(x=>`<button data-mission-open="${x.id}" class="skill-badge ${x.status==='demonstrated'?'earned':''}" aria-pressed="${x.id===m.id}"><span class="badge-art">${MissionArt.svg(x.id)}</span><strong>${esc(x.badge)}</strong><small>${x.extension?'EXTENSION · ':''}${names[x.status]}</small></button>`).join('')}</div><article class="mission-detail" tabindex="-1"><p class="eyebrow">${m.objective} · ${m.extension?'EXTENSION':'CORE'} · ${names[s]}</p><h3>${esc(m.title)}</h3><p class="mission-criteria"><b>Badge criteria:</b> correct linked video check + completed objective workshop (including self-assessment) + a model reflection + both mission questions correct, with at least 24 hours between successful challenges.</p><div class="mission-path"><span class="${videoDone?'done':''}">1 · Watch &amp; check ${videoDone?'✓':''}</span><span class="${courseDone?'done':''}">2 · Explore &amp; explain ${courseDone?'✓':''}</span><span class="${r?.practiceAt?'done':''}">3 · Apply ${r?.practiceAt?'✓':''}</span><span class="${s==='demonstrated'?'done':''}">4 · Recheck ${s==='demonstrated'?'✓':''}</span></div><div class="mission-resources"><button data-open-video="${m.video}">Open linked video &amp; check →</button><button data-open-objective="${m.objective}">Open ${m.objective} model &amp; objective practice →</button></div><label class="mission-reflection">${esc(m.reflection)}<textarea data-mission-reflection maxlength="1500" rows="3" ${r?.practiceAt?'readonly':''} placeholder="Record your prediction, observation and explanation…">${esc(r?.reflection||'')}</textarea></label><p class="small">Save a reflection of at least 20 characters. Length is a participation check, not automated marking of your explanation.</p>${!r?.practiceAt?'<button data-save-reflection>Save reflection</button>':''}${!ready(m,e)&&!r?.practiceAt?'<p>Complete the linked video check and objective workshop before attempting the application challenge.</p>':''}${question(m,r,'initial',!ready(m,e)||!r?.reflection||r.reflection.trim().length<20||!!r.practiceAt)}${r?.practiceAt?`<section class="mission-recheck"><h4>${s==='demonstrated'?'Skill badge earned':s==='waiting'?'Let the learning settle':'Test your recall in a new context'}</h4>${s==='waiting'?`<p>Your different follow-up question unlocks ${new Date(r.practiceAt+C.delay).toLocaleString('en-AU')}. Return whenever you are ready after that; there is no expiry or penalty.</p><button data-mission-refresh>Check availability</button>`:question(m,r,'recheck',s==='demonstrated')}${s==='demonstrated'?`<p class="badge-earned">✦ ${esc(m.badge)} · earned ${new Date(r.recheck.at).toLocaleDateString('en-AU')}</p><p>You applied this skill in two different questions with a delay between them. Keep testing it in objective practice and mocks.</p>`:''}</section>`:''}<p><button data-route="studentDashboard">Return to dashboard →</button></p></article>`;
root.querySelector('[data-save-reflection]')?.addEventListener('click',()=>{const text=root.querySelector('textarea').value;state=get();state.records[m.id]??={version:m.version,initial:null,recheck:null,practiceAt:0};state.records[m.id].reflection=text;save();render();root.querySelector('.mission-detail').focus({preventScroll:true});});root.querySelectorAll('form').forEach(f=>f.onsubmit=event=>{event.preventDefault();const a=f.querySelector('input:checked');if(!a)return;state=C.answer(get(),B,m.id,f.dataset.missionAnswer,Number(a.value),ready(m,evidence()),Date.now());save();render();root.querySelector('.mission-detail').focus({preventScroll:true});});root.querySelector('[data-mission-refresh]')?.addEventListener('click',render);milestones();}
window.Missions={key:C.key,get,summary,dashboard,open(id){if(B.some(m=>m.id===id))selected=id;render();root.querySelector('.mission-detail')?.scrollIntoView({block:'start',behavior:'auto'});root.querySelector('.mission-detail')?.focus({preventScroll:true});}};
window.addEventListener('science-progress-changed',milestones);window.addEventListener('science-mock-updated',milestones);window.addEventListener('storage',()=>{milestones();if(!root.hidden)render()});window.addEventListener('science-missions-open',render);document.addEventListener('visibilitychange',()=>{if(!document.hidden){milestones();if(!root.hidden)render()}});render();})();
